@Test
fun sameUID_newGeneration_rejectsStalePage_andPreservesFreshState() = runBlocking {
    val load1Started = CompletableDeferred<Unit>()
    val releaseLoad1 = CompletableDeferred<Unit>()
    var count = 0

    val client = createClient { req ->
        val path = req.url.encodedPath
        if (path.contains("admin_get_member_credit_history")) {
            count++
            if (count == 1) {
                load1Started.complete(Unit)
                releaseLoad1.await()
                respond(
                    """{"items":[{"id":"stale-cred","user_id":"$userTarget","amount":10,"balance":110,"created_at":"2026-11-01T00:00:00Z"}],"has_more":false,"next_cursor":null}""",
                    headers = headersOf(HttpHeaders.ContentType, "application/json")
                )
            } else {
                respond(
                    """{"items":[{"id":"fresh-cred","user_id":"$userTarget","amount":50,"balance":150,"created_at":"2026-11-01T01:00:00Z"}],"has_more":false,"next_cursor":null}""",
                    headers = headersOf(HttpHeaders.ContentType, "application/json")
                )
            }
        } else {
            respond("{}", headers = headersOf(HttpHeaders.ContentType, "application/json"))
        }
    }
    login(client, adminA)

    val adminMgmtRepo = AdminManagementRepository(client)
    val vm = MemberDetailViewModel(userTarget, adminMgmtRepo, AuthRepository(client, context), localizer)
    load1Started.await()

    // Same UID but new session generation
    SessionCacheManager.clear(context)
    val genAfter = SessionCacheManager.currentGeneration()
    login(client, adminA) // triggers session re-auth with new generation
    waitUntil { vm.uiState.value.sessionGeneration == genAfter && !vm.uiState.value.isLoading }

    // Release stale Load 1 from generation 1
    releaseLoad1.complete(Unit)
    testDispatcher.scheduler.runCurrent()

    // Stale response must NOT overwrite or add to fresh generation state
    assertTrue("Stale generation response must be rejected", vm.uiState.value.creditHistory.none { it.id == "stale-cred" })
}

